SELECT ?property ?propertyLabel ?value ?valueLabel ?statement ?guid ?start ?end (COUNT(DISTINCT ?reference) AS ?referenceCount) WHERE {
  VALUES ?property { wdt:P31 wdt:P279 wdt:P17 wdt:P1001 wdt:P361 wdt:P2389 wdt:P1448 wdt:P1705 wdt:P1813 wdt:P1308 wdt:P2521 wdt:P3321 wdt:P973 }
  wd:Q141151607 ?property ?value .
  OPTIONAL {
    ?statement ?ps ?value ; wikibase:rank ?rank .
    ?prop wikibase:directClaim ?property ; wikibase:claim ?claim ; wikibase:statementProperty ?ps .
    wd:Q141151607 ?claim ?statement .
    OPTIONAL { ?statement pq:P580 ?start }
    OPTIONAL { ?statement pq:P582 ?end }
    OPTIONAL { ?statement prov:wasDerivedFrom ?reference }
    BIND(REPLACE(STR(?statement), '^.*/statement/', '') AS ?guid)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,ka,ru". }
}
GROUP BY ?property ?propertyLabel ?value ?valueLabel ?statement ?guid ?start ?end
ORDER BY ?property ?value

SELECT ?kind ?lang ?text WHERE {
  {
    wd:Q141151607 rdfs:label ?text .
    BIND("label" AS ?kind)
  } UNION {
    wd:Q141151607 schema:description ?text .
    BIND("description" AS ?kind)
  } UNION {
    wd:Q141151607 skos:altLabel ?text .
    BIND("alias" AS ?kind)
  }
  BIND(LANG(?text) AS ?lang)
  FILTER(?lang IN ("ka","en","ru","hy","az","de","fr","es"))
}
ORDER BY ?kind ?lang ?text

SELECT ?subject ?property ?value ?valueLabel ?statement ?guid ?start ?end (COUNT(DISTINCT ?reference) AS ?referenceCount) WHERE {
  VALUES (?subject ?property) {
    (wd:Q141125846 p:P2388)
    (wd:Q141125846 p:P1037)
    (wd:Q116869957 p:P39)
  }
  ?subject ?property ?statement .
  ?statement ?ps ?value .
  ?prop wikibase:claim ?property ; wikibase:statementProperty ?ps .
  OPTIONAL { ?statement pq:P580 ?start }
  OPTIONAL { ?statement pq:P582 ?end }
  OPTIONAL { ?statement prov:wasDerivedFrom ?reference }
  BIND(REPLACE(STR(?statement), '^.*/statement/', '') AS ?guid)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,ka,ru". }
}
GROUP BY ?subject ?property ?value ?valueLabel ?statement ?guid ?start ?end
ORDER BY ?subject ?property ?start

SELECT ?statement ?guid ?position ?positionLabel ?directedOrg ?directedOrgLabel WHERE {
  wd:Q116869957 p:P39 ?statement .
  ?statement ps:P39 ?position .
  OPTIONAL { ?statement pq:P2389 ?directedOrg }
  BIND(REPLACE(STR(?statement), '^.*/statement/', '') AS ?guid)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,ka,ru". }
}

